solution:
def scoreboard(runs, balls):
    sr = runs * 100 / balls if balls else 0
    return f"{runs} runs in {balls // 6}.{balls % 6} overs, SR {sr:.2f}"

alt:
def scoreboard(runs, balls):
    overs, left = divmod(balls, 6)
    rate = 0.0
    if balls > 0:
        rate = runs / balls * 100
    return f"{runs} runs in {overs}.{left} overs, SR {rate:.2f}"
